"""Jersey number and crest texels (from NHL96PC player_art.asm: MakeJerseyNumber, SetPlayerSpriteColors).
Number image is 7x5 (two 3x5 digits, gap column); texel (r,c) is palette entry 182+16r+c. Crest is 6x6; texel (r,c) is 160+16r+c."""
import numpy as np
DIG=bytes.fromhex('020202020102020102020102020202 010102010102010102010102010202 020201010201020102010102020202 020201010201020101010202020202 010102010202020201010201010202 020202010101020101010202020201 020202010202020102020202020202 010102010201020101020101020202 020201020102010201020202020202 020202010202020202010102020202'.replace(' ',''))
# the table in the game starts with digit 0; rows above are split only for reading
RAW=[0x02,0x02,0x02,0x02,0x01,0x02,0x02,0x01,0x02,0x02,0x01,0x02,0x02,0x02,0x02,0x01,0x01,0x02,0x01,0x01,0x02,0x01,0x01,0x02,0x01,0x01,0x02,0x01,0x01,0x02,0x02,0x02,0x02,0x01,0x01,0x02,0x01,0x02,0x01,0x02,0x01,0x01,0x02,0x02,0x02,0x02,0x02,0x02,0x01,0x01,0x02,0x01,0x02,0x01,0x01,0x01,0x02,0x02,0x02,0x02,0x02,0x01,0x01,0x02,0x01,0x02,0x02,0x02,0x02,0x01,0x01,0x02,0x01,0x01,0x02,0x02,0x02,0x02,0x02,0x01,0x01,0x01,0x02,0x01,0x01,0x01,0x02,0x02,0x02,0x02,0x01,0x02,0x02,0x02,0x01,0x01,0x02,0x02,0x02,0x02,0x01,0x02,0x02,0x02,0x02,0x02,0x02,0x02,0x01,0x01,0x02,0x01,0x02,0x01,0x02,0x01,0x01,0x02,0x01,0x01,0x02,0x02,0x02,0x02,0x01,0x02,0x01,0x02,0x01,0x02,0x01,0x02,0x02,0x02,0x02,0x02,0x02,0x02,0x02,0x01,0x02,0x02,0x02,0x02,0x01,0x01,0x02,0x02,0x02,0x01,0x02,0x01,0x01,0x02,0x01,0x01,0x02,0x01,0x01,0x02,0x01,0x01,0x02,0x01,0x01]
def digit(n):return np.array(RAW[15*n:15*n+15]).reshape(5,3)
def number_image(n):
    im=np.ones((5,7),int)
    if n<10:im[:,2:5]=digit(n)
    else:im[:,0:3]=digit(n//10);im[:,4:7]=digit(n%10)
    return im
NUM=np.array([[182+16*r+c for c in range(7)] for r in range(5)]);CREST=np.array([[160+16*r+c for c in range(6)] for r in range(6)])
def with_number(pal,n,fg=None,bg=None):
    p=pal.copy();im=number_image(n);fg=pal[2] if fg is None else fg;bg=pal[1] if bg is None else bg
    p[NUM]=np.where((im==2)[...,None],fg,bg);return p
if __name__=='__main__':
    for n in (8,1,4):print(digit(n))
    from pal96 import pals;p=pals()['!bfh'];print(p[:4],p[NUM[0]],p[CREST])
